const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const thailand = ee.FeatureCollection('FAO/GAUL/2015/level0')
    .filter(ee.Filter.eq('ADM0_NAME', 'Thailand'))
    .first()
    .geometry();

  const startMonth = 4; // April
  const endMonth = 4;   // April

  const year2016 = 2016;
  const startYearHistorical = 2001;
  const endYearHistorical = 2010;

  // Function to filter MODIS LST collection by quality
  const maskLST = function(image) {
    // Select the LST_Day_01 band. Scale factor is 0.02.
    // The QC_Day band contains quality information.
    // Bits 0-1: LST quality (00 = good quality, 01 = LST produced, other quality)
    // Bits 2-3: LST error flag (00 = average LST error <= 1K)
    // Bits 4-5: Cloud (00 = clear, 01 = cloudy)
    // We want clear sky and good quality.
    var qcDay = image.select('QC_Day');
    var lstDay = image.select('LST_Day_01').multiply(0.02);

    // Get the cloud state (bits 4-5)
    var cloudState = qcDay.rightShift(4).bitwiseAnd(3); // 3 (binary 11) to get bits 4-5
    // Get the LST quality (bits 0-1)
    var lstQuality = qcDay.bitwiseAnd(3); // 3 (binary 11) to get bits 0-1

    // Mask out cloudy pixels (cloudState == 0 means clear)
    // Mask out poor LST quality (lstQuality == 0 means good quality)
    var mask = cloudState.eq(0).and(lstQuality.eq(0));

    return lstDay.updateMask(mask).copyProperties(image, ['system:time_start']);
  };

  // 2. Data Acquisition & Check
  const collection = ee.ImageCollection('MODIS/061/MOD11A2');

  // LST for April 2016
  let col2016 = collection
    .filterDate(ee.Date.fromYMD(year2016, startMonth, 1), ee.Date.fromYMD(year2016, endMonth, 30))
    .map(maskLST);

  if (col2016.size().getInfo() === 0) {
    console.log("C1: No MODIS LST images found for April 2016.");
    console.log("C1");
    return;
  }

  // Calculate mean LST for 2016
  const meanLST2016 = col2016.mean().clip(thailand);

  // LST for April 2001-2010 average
  let historicalAnnualMeans = ee.ImageCollection([]);
  for (let year = startYearHistorical; year <= endYearHistorical; year++) {
    let colYear = collection
      .filterDate(ee.Date.fromYMD(year, startMonth, 1), ee.Date.fromYMD(year, endMonth, 30))
      .map(maskLST);

    if (colYear.size().getInfo() > 0) {
      historicalAnnualMeans = historicalAnnualMeans.add(colYear.mean());
    } else {
      console.log(`Warning: No MODIS LST images found for April ${year}.`);
    }
  }

  if (historicalAnnualMeans.size().getInfo() === 0) {
    console.log("C1: No MODIS LST images found for the historical average period (April 2001-2010).");
    console.log("C1");
    return;
  }

  const meanLSTHistorical = historicalAnnualMeans.mean().clip(thailand);

  // 3. Processing & Calculation
  // Scale for reduceRegion (1km resolution for MODIS LST)
  const scale = 1000; 

  const reduceRegionParams = {
    reducer: ee.Reducer.mean(),
    geometry: thailand,
    scale: scale,
    maxPixels: 1e9
  };

  const lst2016Value = meanLST2016.reduceRegion(reduceRegionParams).get('LST_Day_01');
  const lstHistoricalValue = meanLSTHistorical.reduceRegion(reduceRegionParams).get('LST_Day_01');

  // Check for C2 (No Valid Pixels)
  const count2016 = meanLST2016.reduceRegion(reducer=ee.Reducer.count(), geometry=thailand, scale=scale, maxPixels=1e9).get('LST_Day_01');
  const countHistorical = meanLSTHistorical.reduceRegion(reducer=ee.Reducer.count(), geometry=thailand, scale=scale, maxPixels=1e9).get('LST_Day_01');

  if (count2016.getInfo() === 0 || countHistorical.getInfo() === 0) {
    console.log("C2: No valid pixels remaining after cloud masking and clipping for one or both periods.");
    console.log("2016 Valid Pixels: " + count2016.getInfo());
    console.log("Historical Valid Pixels: " + countHistorical.getInfo());
    console.log("C2");
    return;
  }

  const val2016 = lst2016Value.getInfo();
  const valHistorical = lstHistoricalValue.getInfo();

  // 4. Validation & Final Answer
  if (val2016 === null || isNaN(val2016) || valHistorical === null || isNaN(valHistorical)) {
    console.log("C3: Calculation failure (result is None or NaN).");
    console.log("2016 LST Value: " + val2016);
    console.log("Historical LST Value: " + valHistorical);
    console.log("C3");
    return;
  }

  console.log(`April 2016 LST (Thailand): ${val2016.toFixed(2)} K`);
  console.log(`April 2001-2010 Avg LST (Thailand): ${valHistorical.toFixed(2)} K`);
  console.log(`Difference (2016 - Historical): ${(val2016 - valHistorical).toFixed(2)} K`);
  console.log(`2016 Valid Pixels: ${count2016.getInfo()}`);
  console.log(`Historical Valid Pixels: ${countHistorical.getInfo()}`);

  if (val2016 > valHistorical) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
